update public.poetry as p
set body = x.body
from (
  select x->>'slug' as slug, x->>'body' as body
  from jsonb_array_elements($bodies$[{"slug":"tum-p021","body":"شور کیسا میرے آشیانے سے اٹھتا ہے\nیہ دھواں کیا جلانے سے اڑتا ہے\n\nہم دونوں ہیں فقط بربادی کی راہوں پہ\nہر راستہ ہی شاید وہیں کو چلتا ہے\n\nجب مرنا ہے مقدر تو آو ساتھ جیئیں\nاپنی منزلوں کا تو ایک ہی راستہ ہے\n\nیوں نہ بچھڑو کہ دل پھر کبھی نہ سنبھلے\nیہ روگ محبت کا گھروں کو ڈھستا ہے\n\nاحمد تو اب رونق محفل بھی نہیں\nپھرکیوں یہ آئینہ مجھ پہ ہنستا ہے"},{"slug":"tum-p022","body":"اپنا تھا یا سراب کوئی\nملتا نہیں ہے جواب کوئی\n\nہم کہ نیند سے بھی گئے\nکیا ہی دیکھتے خواب کوئی\n\nآپ ہیں ابھی بھی سرِ فہرست\nاپنا کہاں ہے حساب کوئی\n\nساقی کے آنے، نہ آنے پہ\nچھوڑے گا کیا شراب کوئی\n\nآج اس طرح مسکرائے ہم\nدکھنے لگا اضطراب کوئی\n\nوہ نینہ جو سوکھے تھے\nان میں تھا سیلاب کوئی\n\nکسی کے کسی کو ملنے پہ\nکیوں ہوا بےتاب کوئی\n\nوہ زندگی جو خار جیے\nکیا جانے گلاب کوئی\n\nاپنی خود کی کتاب کا\nپڑھ نہ پایا باب کوئی\n\nسب کی اپنی نظر، کوئی آتش\nکسی کے لیے ہے آب کوئی\n\nاحمد کیا کسی کو یاد کرے\nاحمد کو تھا دستیاب کوئی؟"},{"slug":"tum-p023","body":"یوں تو پھیلا نہ کسی سو شور سہی کا\nشہر  بھر میں عام ہے چرچا تیرے نہی کا\n\nتم نے خود چنا تھا مجھے اور شاعر کہا\nمیں توعام سا لڑکا تھا ایک تنگ گلی کا"},{"slug":"tum-p024","body":"ہنگامِ سحر میں جو ہیں گم انھیں سونے دو\nشب بیدار ہیں جو صنم انھیں رونے دو\nیہ کیسی شہر بھر میں وبا پھیلی ہے نئی\nجو ہوتا ہے ، اچھا ہے ، ہونے دو\n\nیہ کہاں کا دیں ، کہاں کا امیں\nکہ سب ہی مظلوم سب ہی ظالم\nہر فرد کی سوچ پہ فرد کا قبضہ\nہر فرد ہے نابینا مگر بینا ہے حاکم\n\nہمارے درد کے جو فلک پہ ستارے ہیں\nیہ دہر کی ہر گور سے بہت زیادہ ہیں\nہماری ارواح پہ بےکسی کے جو چھالے ہیں\nوہ جسم کے نشانوں سے بہت زیادہ ہیں\n\nیہ درد نینوں کے ابر سے برسنے بھی دو\nکیا خبر کہ یہ نیناں گرجنا چھوڑیں\nکیا پتا یہ خوف کی چٹانیں ٹوٹنے لگیں\nممکن ہے قسمت کے شہاب گرنا چھوڑیں\n\nپھر کوئی دیپ شہر بھر میں ایسا جلاو\nکوچے کوچے میں نہاں ایندھن کو چنگاری ملے\nوحشتوں میں ڈوبتے بےحس دلوں کو\nساحل دکھے ، ناخداوں سے پُر سواری ملے\n\nسر بلند کرو چلو لیے قلم کی تیغ\nپھر جو کہتا ہے زمانہ اسے کہنے دو\nپہلے اپنے حصے کا ثمر بنجر پہ لگاو\nپھر کہو ! جو ہوتا ہے ،اچھا ہے ، ہونے دو"},{"slug":"tum-p025","body":"صبحِ فراق خاک آنکھوں میں ملتی رہی\nشب دل  بھی جلتا رہا رات بھی ڈھلتی رہی\nمنڈلاتی رہی تیرے خلوص کی جھلکیاں ذہن پہ\nتلخیِ وقت بھی شمشیر بن کے لٹکتی رہی\n\nبرستی رہی کھڑکیوں پہ ساون کی  تیز گھٹا\nاورگہرا سا نشاں شیشے پہ چھوڑ گئی\nجانے کون کون سا پہلو کون کون سا گھاؤ\nاب وفا دل کی ویرانیوں سے کس موڑ گئی\n\nگرج پڑے بادل ، رم جھم رم جھم ہے دیرینہ آس\nدل کے باغیچے میں  پڑی ہے کسی یاد کی لاش\nوحشت زدہ ہے سماں اور خاموش مکاں ہے\nنہ کوئی جادۂِ منزل ، نہ کوئی حرفِ کاش\n\nہر سُو فضا میں پھیلی ہے اداسیوں کی ہوا\nبھر رہا ہے زخم ، تھم گئی ہے گھٹا\nآرزو کسی کے لمس کی اب زباں پہ نہیں\nسل گئے ہیں لب پر باقی ہے یہ صدا\n\nکہ ابھی اور روداد ہے جو سنانے کو ہے\nمنظر دھندلا ہے مگر منزل آنے کو ہے\nکبھی ، کہیں ، مگر جلد ہی صحیح\nاحمد ؔ  اپنا اچھا وقت بس آنے کو ہے"}]$bodies$::jsonb) x
) as x
where p.slug = x.slug;
